$ErrorActionPreference="Stop"
try{$R=Split-Path -Parent $MyInvocation.MyCommand.Path;Set-Location $R;if(!(Test-Path "docs")){throw "docs not found"};$bk="_backup_network_classics29_"+(Get-Date -Format "yyyyMMdd-HHmmss");New-Item -ItemType Directory -Force $bk|Out-Null;foreach($s in Get-ChildItem "_payload\docs" -Recurse -File){$rel=$s.FullName.Substring((Resolve-Path "_payload\docs").Path.Length+1);$d=Join-Path "docs" $rel;$dd=Split-Path $d -Parent;if(!(Test-Path $dd)){New-Item -ItemType Directory -Force $dd|Out-Null};if(Test-Path $d){$safe=$rel.Replace("\","_");Copy-Item $d (Join-Path $bk $safe) -Force};Copy-Item $s.FullName $d -Force};Write-Host "NETWORK CLASSICS SASANG MODERNIZATION 29 COMPLETE" -ForegroundColor Green;Write-Host "9 legacy pages rebuilt in place, not appended." -ForegroundColor Cyan;Write-Host ("Backup: "+$bk) -ForegroundColor Yellow}catch{Write-Host ("ERROR: "+$_.Exception.Message) -ForegroundColor Red};Read-Host "Press Enter to close"